using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace ExpenseManagement.Api.Models;

/// <summary>
/// Stored in the "users" collection.
/// Example document: { _id: ObjectId("..."), name: "Ana", email: "ana@example.com", createdAt: ISODate("...") }
/// </summary>
public class User
{
    // _id is the primary key of every MongoDB document. ObjectId is generated by the
    // driver (12 bytes: timestamp + random + counter), so no IDENTITY column is needed.
    // We expose it as a string in C# to keep DTOs and routes simple.
    [BsonId]
    [BsonRepresentation(BsonType.ObjectId)]
    public string Id { get; set; } = null!;

    public string Name { get; set; } = null!;

    /// <summary>Stored lowercased; protected by a unique index.</summary>
    public string Email { get; set; } = null!;

    public DateTime CreatedAt { get; set; }
}
